( 
  $additionalFields := inputData.application.customFields.questionAnswers.additionalFields; 
  $additionalFiles := inputData.application.customFields.questionAnswers.additionalFiles; 

  $fieldQuestionKeys := $filter($keys($additionalFields), function($key) { 
    $substring($key, 0, 9) = "question_" 
  }); 
  $fieldAnswers := $count($fieldQuestionKeys) > 0 ? $map($fieldQuestionKeys, function($key) { 
    ( 
      $id := $number($replace($key, "question_", "")); 
      $value := $lookup($additionalFields, $key); 
      $textArray := $type($value) = "array" ? $value : [$value]; 
      { 
        "question_id": $id, 
        "text": $textArray 
      } 
    ) 
  }) : []; 

  $fileQuestionKeys := $filter($keys($additionalFiles), function($key) { 
    $substring($key, 0, 9) = "question_" 
  }); 
  $fileAnswers := $count($fileQuestionKeys) > 0 ? $map($fileQuestionKeys, function($key) { 
    ( 
      $val := $lookup($additionalFiles, $key); 
      $val != null and $val != "" ? ( 
        $id := $number($replace($key, "question_", "")); 
        $textArray := $type($val) = "array" ? $val : [$val]; 
        { 
          "question_id": $id, 
          "text": $textArray 
        } 
      ) 
    ) 
  }) : []; 

  $allAnswers := $append($fieldAnswers, $fileAnswers); 

  $nonQuestionFileKeys := $filter($keys($additionalFiles), function($key) { 
    $substring($key, 0, 9) != "question_" 
  }); 
  $filesObj := $count($nonQuestionFileKeys) > 0 ? $merge($map($nonQuestionFileKeys, function($key) { 
    ( 
      $val := $lookup($additionalFiles, $key); 
      $val != null and $val != "" ? { $key & "_url": $val } 
    ) 
  })) : {}; 

  $cvUrl := inputData.application.attachment.attachmentLocalPath; 

  $base := { 
    "job_id": inputData.application.atsJobId, 
    "first_name": inputData.candidate.firstName, 
    "last_name": inputData.candidate.lastName, 
    "email": inputData.candidate.email, 
    "phone_number": inputData.candidate.phoneNumbers[0].phoneNumber, 
    "message": inputData.application.customFields.questionAnswers.additionalFields.message, 
    "source_type": "applied", 
    "source_json": { 
      "partner_name": inputData.application.source 
    }, 
    "answers": $allAnswers 
  }; 

  $cvObj := $cvUrl != null and $cvUrl != "" ? { "cv_url": $cvUrl } : {}; 

  $merge([$base, $cvObj, $filesObj]) 
)
